{
  "lecture": [
    {
      "etiquette": "F11",
      "R1": {
        "valeur": 1,
        "passage": "au moins deux composantes plantées de plus couvertes à la sixième génération, à coût égal"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes, lues par l'oracle après la course ; témoin à coût égal : même course sans note servie"
      },
      "R3": {
        "valeur": 0,
        "motif": "La fiche sert une note numérique de nouveauté aux proposeurs sans nommer l'objection établie ni expliquer pourquoi elle ne s'applique pas."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "La distance à l'archive dont dépend la note n'est pas définie par une formule ou un algorithme déterminé."
      },
      "R6": {
        "valeur": 1,
        "passage": "une course à six générations par graine"
      },
      "R7": {
        "valeur": 0,
        "motif": "S'éloigner de l'archive n'implique pas de couvrir davantage de composantes vraies, puisque cet éloignement peut aussi produire des lois absurdes."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F12",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de copies promues diminue d'au moins 5 % par rapport à la course de référence"
      },
      "R2": {
        "valeur": 1,
        "passage": "nombre de copies promues, lu par l'oracle après la course ; témoin : une modification tirée au hasard, au même coût"
      },
      "R3": {
        "valeur": 1,
        "passage": "Le reste de l'organisme ne change pas : mêmes proposeurs, même juge, mêmes plafonds, même monde."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 0,
        "motif": "Le plafond à tripler n'est pas identifié et la fiche affirme simultanément conserver les mêmes plafonds."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars d'appels par graine"
      },
      "R7": {
        "valeur": 0,
        "motif": "Dire que les groupes de doublons se forment autrement ne donne aucune raison impliquant une diminution des copies promues."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F13",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées couvertes augmente d'au moins 5 % par rapport à la course de référence"
      },
      "R2": {
        "valeur": 1,
        "passage": "nombre de composantes plantées couvertes, lu par l'oracle après la course ; témoin : la même course avec les graines permutées, au même budget"
      },
      "R3": {
        "valeur": 1,
        "passage": "Le reste de l'organisme ne change pas : mêmes proposeurs, même juge, mêmes plafonds, même monde."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche ne nomme aucune garantie statistique maintenue ni le nul contre lequel elle serait démontrable."
      },
      "R5": {
        "valeur": 0,
        "motif": "La loi du tirage, la valeur de référence et la règle assurant le budget égal ne sont pas précisées."
      },
      "R6": {
        "valeur": 0,
        "motif": "Un témoin est nommé, mais la mention d'un rejeu sur processeur ne donne aucun ordre de grandeur du coût en calcul ou en tirages."
      },
      "R7": {
        "valeur": 0,
        "motif": "La dépendance de la variance au nombre d'épisodes n'implique pas qu'une variation aléatoire de ce nombre augmente la couverture."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F14",
      "R1": {
        "valeur": 1,
        "passage": "composantes distinctes couvertes par les cartes brutes passe d'une médiane ≤ 2 par monde (témoin : six cartes en un appel, constat v67 \" 11 variantes d'un même constat \") à une médiane ≥ 3"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes, étage des propositions brutes puis des retenues ; copies et lois fausses promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "sans masquer l'archive ni imposer de quota de formes ni récompenser la nouveauté : seule la structure des appels change."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "appels 2 à 7 (sessions neuves, sans historique) = vue habituelle + un seul constat + consigne d'une carte au gabarit. Plafond de jetons de sortie total égal à celui du bras actuel."
      },
      "R6": {
        "valeur": 1,
        "passage": "15 mondes × 2 bras × 4 proposeurs × 7 appels courts ; ordre de quelques dizaines de dollars."
      },
      "R7": {
        "valeur": 1,
        "passage": "La séparation des sessions supprime la pression de cohérence interne d'un appel unique (toutes les cartes alignées sur le premier constat)"
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F15",
      "R1": {
        "valeur": 1,
        "passage": "à coût égal en tirages frais, au moins deux composantes plantées de plus couvertes par monde, et pas plus d'une loi fausse promue sur quarante mondes"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes et lois fausses promues, lues par l'oracle après la course ; témoin à coût égal : le juge actuel avec le même nombre de tirages frais"
      },
      "R3": {
        "valeur": 0,
        "motif": "La validation de chaque carte au seuil 1/α remplace la règle de promotion sans préserver un contrôle démontrable des comparaisons multiples."
      },
      "R4": {
        "valeur": 1,
        "passage": "ce qui contrôle l'erreur de première espèce au niveau α même quand on décide en cours de route d'ajouter ou d'arrêter des expériences."
      },
      "R5": {
        "valeur": 0,
        "motif": "Les tests produisant les valeurs p, leur conversion en valeurs e et les conditions de validité du produit adaptatif ne sont pas spécifiés."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars d'appels par génération pour l'agent qui conçoit les expériences"
      },
      "R7": {
        "valeur": 0,
        "motif": "La validité sous arrêt optionnel ne fournit pas de mécanisme impliquant une couverture supérieure à nombre égal de tirages frais."
      },
      "N": {
        "valeur": "C2",
        "passage_fiche": "chaque expérience rend une valeur p, convertie en valeur e ; les valeurs e se combinent au fil des expériences, et la carte n'est validée que si la valeur e combinée dépasse 1/α",
        "passage_catalogue": "chaque valeur p est convertie en **valeur e** ; les valeurs e se combinent ; l'hypothèse est validée quand la valeur e combinée dépasse 1/α"
      }
    }
  ]
}
